function identity(item){
  if(Array.isArray(item)) return String(item[0] ?? item[1] ?? '').trim().toLowerCase();
  if(item && typeof item==='object') return String(item.code ?? item.name ?? item.username ?? JSON.stringify(item)).trim().toLowerCase();
  return String(item ?? '').trim().toLowerCase();
}
function mergeRows(existing,incoming){
  if(!Array.isArray(existing)) return incoming;
  const seen=new Set(existing.map(identity).filter(Boolean)); const merged=[...existing];
  for(const item of incoming){ const key=identity(item); if(!key || !seen.has(key)){ merged.push(item); if(key) seen.add(key); } }
  return merged;
}
export async function restorePreviousErpDataOnce(){
  const marker='dfab-restored-preclean-data-v3-verified';
  const criticalKeys=['dfab-erp-products-v3','dfab-erp-customers-v2','dfab-erp-vendors-v2','dfab-erp-sales-invoices-v2'];
  const expected=Object.fromEntries(criticalKeys.map(key=>[key,Array.isArray(restoredSeedData[key])?restoredSeedData[key].length:0]));
  const complete=criticalKeys.every(key=>Array.isArray(readCloudValue(key,undefined)) && readCloudValue(key,[]).length>=expected[key]);
  if(readCloudValue(marker,false)===true && complete) return {restored:false,sections:0,verified:true,counts:expected};

  resetCloudWriteErrors();
  let sections=0;
  for(const [key,incoming] of Object.entries(restoredSeedData)){
    const current=readCloudValue(key,undefined);
    const next=Array.isArray(incoming)?mergeRows(Array.isArray(current)?current:[],incoming):(current??incoming);
    if(JSON.stringify(current)!==JSON.stringify(next)){ writeCloudValue(key,next); sections++; }
  }
  await flushCloudWrites();

  const postComplete=criticalKeys.every(key=>Array.isArray(readCloudValue(key,undefined)) && readCloudValue(key,[]).length>=expected[key]);
  if(!postComplete) throw new Error('ERP data restore did not reach the expected record counts. The restore marker was not written.');

  resetCloudWriteErrors();
  writeCloudValue(marker,true);
  await flushCloudWrites();
  return {restored:true,sections,verified:true,counts:Object.fromEntries(criticalKeys.map(key=>[key,readCloudValue(key,[]).length]))};
}

export function getRestoredDataStatus(){
  const keys=['dfab-erp-products-v3','dfab-erp-customers-v2','dfab-erp-vendors-v2','dfab-erp-sales-invoices-v2'];
  const counts=Object.fromEntries(keys.map(key=>[key,Array.isArray(readCloudValue(key,undefined))?readCloudValue(key,[]).length:0]));
  return {
    counts,
    products:counts['dfab-erp-products-v3'],
    customers:counts['dfab-erp-customers-v2'],
    vendors:counts['dfab-erp-vendors-v2'],
    invoices:counts['dfab-erp-sales-invoices-v2'],
    complete:counts['dfab-erp-products-v3']>=2118 && counts['dfab-erp-customers-v2']>=220 && counts['dfab-erp-vendors-v2']>=422 && counts['dfab-erp-sales-invoices-v2']>=84
  };
}
